@MainActor func transient_SymbolSegment_objectDisplay (
       _ self_x1 : CanariLength,                       
       _ self_y1 : CanariLength,                       
       _ self_x2 : CanariLength,                       
       _ self_y2 : CanariLength,                       
       _ prefs_symbolColor : NSColor,                  
       _ prefs_symbolDrawingWidthMultipliedByTen : Int
) -> EBShape {
//--- START OF USER ZONE 2
    var bp = BezierPath ()
    bp.move (to: NSPoint (x: self_x1, y: self_y1))
    bp.line (to: NSPoint (x: self_x2, y: self_y2))
    bp.lineWidth = CanariLength.pt (prefs_symbolDrawingWidthMultipliedByTen) / 10.0
    bp.lineCapStyle = .round
    var shape = EBShape ()
    shape.add (stroke: [bp], prefs_symbolColor)
    return shape
//--- END OF USER ZONE 2
}

